import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    static long totalCost;

    // Cost of k complete rounds: totalCost * k * (k + 1) / 2.
    static long spent(long rounds) {
        return totalCost * (rounds * (rounds + 1) / 2);
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long money = nextLong();
        long[] costs = new long[n];
        for (int i = 0; i < n; i++) {
            costs[i] = nextLong();
            totalCost += costs[i];
        }
        long low = 0, high = 1;
        while (spent(high) <= money) high *= 2;
        while (low + 1 < high) {
            long middle = (low + high) / 2;
            if (spent(middle) <= money) low = middle;
            else high = middle;
        }
        long remaining = money - spent(low), bought = low * n, multiplier = low + 1;
        // Partial round: stop at the first item that cannot be afforded.
        for (long c : costs) {
            long price = multiplier * c;
            if (price > remaining) break;
            remaining -= price;
            bought++;
        }
        System.out.println(bought);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, money := nextInt(), nextInt()
	costs := make([]int, n)
	totalCost := 0
	for i := range costs {
		costs[i] = nextInt()
		totalCost += costs[i]
	}
	// Cost of k complete rounds: totalCost * k * (k + 1) / 2.
	spent := func(rounds int) int { return totalCost * (rounds * (rounds + 1) / 2) }
	low, high := 0, 1
	for spent(high) <= money {
		high *= 2
	}
	for low+1 < high {
		middle := (low + high) / 2
		if spent(middle) <= money {
			low = middle
		} else {
			high = middle
		}
	}
	remaining, bought, multiplier := money-spent(low), low*n, low+1
	// Partial round: stop at the first item that cannot be afforded.
	for _, c := range costs {
		price := multiplier * c
		if price > remaining {
			break
		}
		remaining -= price
		bought++
	}
	fmt.Println(bought)
}
